'use strict';

const KEY_RE = /^[A-Z][A-Z0-9_]*$/;
const CANONICAL_UINT_RE = /^(?:0|[1-9][0-9]*)$/;

// Known fields in schema order, with inclusive integer ranges.
const SCHEMA = [
  ['WINDOW', 1, 20],
  ['RATE', 0, 10],
  ['LIMIT', 1, 25],
];

function formatError() {
  return new Error('INVALID_FORMAT');
}

function valueError() {
  return new Error('INVALID_VALUE');
}

// Split decoded field text into [key, value] and validate syntax.
// Unquoted fields must contain exactly one '='; quoted fields may contain
// further '=' characters inside the value, so split at the first one.
function splitField(raw, quoted) {
  const eq = raw.indexOf('=');
  if (eq === -1) throw formatError();
  if (!quoted && raw.indexOf('=', eq + 1) !== -1) throw formatError();
  const key = raw.slice(0, eq);
  const value = raw.slice(eq + 1);
  if (!KEY_RE.test(key)) throw formatError();
  if (value !== value.trim()) throw formatError();
  return [key, value];
}

// Validate one record's fields syntactically, then semantically.
function buildRecord(fields) {
  // Map without a prototype so keys such as "__proto__" stay plain data.
  const seen = new Map();
  for (const { raw, quoted } of fields) {
    const [key, value] = splitField(raw, quoted);
    if (seen.has(key)) throw formatError();
    seen.set(key, value);
  }

  const record = {};
  for (const [name, min, max] of SCHEMA) {
    if (!seen.has(name)) throw valueError();
    const text = seen.get(name);
    if (!CANONICAL_UINT_RE.test(text)) throw valueError();
    const n = Number(text);
    if (!Number.isSafeInteger(n) || n < min || n > max) throw valueError();
    record[name] = n;
  }
  // Unknown keys are dropped after syntax and duplicate validation.
  return record;
}

function parseRecords(text) {
  if (typeof text !== 'string') throw formatError();
  if (text === '') return [];

  const out = [];
  const len = text.length;
  let i = 0;

  // Each iteration parses one record, then validates it before moving on,
  // so a record's own syntax errors take precedence over its semantic errors.
  while (i < len) {
    const fields = [];
    let recordDone = false;

    while (!recordDone) {
      let raw = '';
      let quoted = false;

      if (i < len && text[i] === '"') {
        quoted = true;
        i++;
        let closed = false;
        while (i < len) {
          const c = text[i];
          if (c === '"') {
            if (text[i + 1] === '"') {
              raw += '"';
              i += 2;
            } else {
              i++;
              closed = true;
              break;
            }
          } else {
            raw += c;
            i++;
          }
        }
        if (!closed) throw formatError();
        // Only a separator, a record ending, or end of input may follow.
        if (i < len && text[i] !== ';' && text[i] !== '\n' && text[i] !== '\r') {
          throw formatError();
        }
      } else {
        while (i < len) {
          const c = text[i];
          if (c === ';' || c === '\n' || c === '\r') break;
          if (c === '"') throw formatError();
          raw += c;
          i++;
        }
      }

      fields.push({ raw, quoted });

      if (i >= len) {
        recordDone = true;
      } else if (text[i] === ';') {
        i++;
      } else {
        // Record ending: CRLF, LF, or CR.
        if (text[i] === '\r' && text[i + 1] === '\n') i += 2;
        else i++;
        recordDone = true;
      }
    }

    out.push(buildRecord(fields));
  }

  return out;
}

module.exports = { parseRecords };
